$c_file = ENGINE_DIR . '/data/peestream.conf.php';
$peestream_config = array();
if( file_exists( $c_file ) ) {
	include( $c_file );
}
if( is_array( $peestream_config ) ) {
	$need_save = false;
	if( empty( $peestream_config['webhook_secret'] ) || strlen( $peestream_config['webhook_secret'] ) < 16 || $peestream_config['webhook_secret'] === '529c675e950e1f3b3e3d27415b8437d54923b5c21f331241' ) {
		$peestream_config['webhook_secret'] = bin2hex( random_bytes( 24 ) );
		$need_save = true;
	}
	if( empty( $peestream_config['cron_secret'] ) || strlen( $peestream_config['cron_secret'] ) < 16 || $peestream_config['cron_secret'] === $peestream_config['webhook_secret'] ) {
		$peestream_config['cron_secret'] = bin2hex( random_bytes( 24 ) );
		$need_save = true;
	}
	if( $need_save ) {
		$content = "<?PHP\n\n\$peestream_config = " . var_export( $peestream_config, true ) . ";\n\n?>";
		@file_put_contents( $c_file, $content );
	}
}
